const out = ($input.first().json.stdout || '').trim();
const nodePortMatch = out.match(/---\s*nodeport\s*---\s*\n?(\d+)/i);
const nodePort = nodePortMatch ? nodePortMatch[1] : 'unknown';
const restartsMatch = out.match(/crashloop-demo\s+\S+\s+(\S+)\s+(\d+)/);
const status = restartsMatch ? restartsMatch[1] : 'CrashLoopBackOff';
const restarts = restartsMatch ? restartsMatch[2] : 'multiple';

const shortDescription = `Pod 'crashloop-demo' is in CrashLoopBackOff on Worker1OL (namespace: default)`;
const description = `Pod 'crashloop-demo' in namespace 'default' on host Worker1OL is stuck in ${status} after ${restarts} restarts. The pod's container exits immediately on every start attempt and kubelet keeps restarting it per restartPolicy.\n\nIt is exposed as a NodePort Service 'crashloop-demo' on port ${nodePort} -- the service currently has no healthy backend to route to.\n\nLive diagnostic evidence (kubectl get pods / describe pod):\n${out}`;

return [{
  json: {
    shortDescription,
    description,
    configurationItem: 'Worker1OL',
    priority: 'P2',
    impact: 'DEPARTMENT',
    urgency: 'HIGH',
    callerName: 'n8n Telemetry Engine',
    generatedAt: new Date().toISOString()
  }
}];

const res = $input.first().json;
const body = res.body || res;

return [{
  json: {
    status: 'SUCCESS',
    incidentNumber: body.number || body.id,
    title: body.shortDescription,
    configurationItem: body.configurationItem || body.configurationItemName,
    priority: body.priority,
    state: body.state,
    createdAt: body.createdAt || new Date().toISOString(),
    message: `[n8n] Filed ${body.priority} incident ${body.number || body.id} for CrashLoopBackOff pod 'crashloop-demo' on ${body.configurationItem || body.configurationItemName}`
  }
}];
